+test("ajuste: recuento menor agrega un egreso por la diferencia", () => {
+  const antes = conIngreso();
+  const despues = ajustarInventario(antes, { articulo: "A1", almacen: "LPZ", cantidadContada: 7, motivo: "merma" });
+  assert.equal(antes.length, 1);
+  assert.equal(despues.length, 2);
+  assert.deepEqual(despues[1], { tipo: "egreso", articulo: "A1", almacen: "LPZ", cantidad: 3, motivo: "merma" });
+  assert.equal(stock(despues, "A1", "LPZ"), 7);
+});
+
+test("ajuste: recuento mayor agrega un ingreso por la diferencia", () => {
+  const despues = ajustarInventario(conIngreso(), { articulo: "A1", almacen: "LPZ", cantidadContada: 12, motivo: "hallazgo" });
+  assert.equal(despues[1].tipo, "ingreso");
+  assert.equal(despues[1].cantidad, 2);
+  assert.equal(stock(despues, "A1", "LPZ"), 12);
+});
+
+test("ajuste: sin diferencia no agrega nada", () => {
+  const antes = conIngreso();
+  const despues = ajustarInventario(antes, { articulo: "A1", almacen: "LPZ", cantidadContada: 10, motivo: "recuento" });
+  assert.equal(despues.length, 1);
+  assert.deepEqual(despues, antes);
+});
+
+test("ajuste: recuento inválido se rechaza y nunca deja stock negativo", () => {
+  assert.throws(() => ajustarInventario(conIngreso(), { articulo: "A1", almacen: "LPZ", cantidadContada: -1, motivo: "x" }), RangeError);
+  assert.throws(() => ajustarInventario(conIngreso(), { articulo: "A1", almacen: "LPZ", cantidadContada: 1.5, motivo: "x" }), RangeError);
+  assert.throws(() => ajustarInventario(conIngreso(), { articulo: "A1", almacen: "LPZ", cantidadContada: 5 }), /motivo/);
+});
